const datosEntrada = $input.first();

const imagen = datosEntrada.binary?.Imagen;

if (!imagen) {
  throw new Error("No se ha recibido ninguna imagen");
}

if (!["image/jpeg", "image/png"].includes(imagen.mimeType)) {
  throw new Error("Formato de imagen no permitido");
}

return [{
  json: {
    archivo: imagen.fileName,
    formato: imagen.mimeType,
    resultado: "Imagen recibida correctamente",
    intentos: Number(datosEntrada.json.intentos ?? 0)
  },
  binary: datosEntrada.binary
}];

const item = $input.first();
if (!item.binary?.Imagen) throw new Error('Falta la imagen');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'Imagen');
if (buffer.length > 8 * 1024 * 1024) throw new Error('La imagen supera los 8 MiB');
return [{json:{...item.json, tamanoBytes:buffer.length, imagenBase64:buffer.toString('base64'), intentos:0},binary:item.binary}];

const respuesta = $input.first().json.message?.content;
const origen = $("03 - Preparar imagen Base66").first();

let documento;
let errorInterpretacion = null;

try {
  if (typeof respuesta !== "string" || !respuesta.trim()) {
    throw new Error("Respuesta vacía");
  }

  const limpio = respuesta
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  documento = JSON.parse(limpio);

  if (
    !documento ||
    typeof documento !== "object" ||
    Array.isArray(documento)
  ) {
    throw new Error("Respuesta JSON incorrecta");
  }

} catch (error) {
  errorInterpretacion = error.message;

  documento = {
    estado: "REVISION_MANUAL",
    tipo_documento: "INDETERMINADO",
    motivo: "No se pudo interpretar la respuesta de la IA",
    documento_visible: null,
    documento_completo: null,
    numero_principal_completo: null,
    mano_externa_visible: null,
    persona_externa_visible: null
  };
}

// 1. Normalizar valores
const estadoIA = String(documento.estado ?? "")
  .trim()
  .toUpperCase();

const tipoDocumento = String(documento.tipo_documento ?? "")
  .trim()
  .toUpperCase();

const documentoVisible =
  documento.documento_visible === true;

const documentoCompleto =
  documento.documento_completo === true;

const numeroPrincipalCompleto =
  documento.numero_principal_completo === true;

const manoVisible =
  documento.mano_externa_visible === true;

const personaVisible =
  documento.persona_externa_visible === true;

// 2. Comprobar categoría documental
const tiposAdmitidos = [
  "DNI_NIF",
  "TIE_NIE",
  "ID_NACIONAL",
  "PASAPORTE"
];

const tipoAdmitido =
  tiposAdmitidos.includes(tipoDocumento);

// 3. Comprobar que se puede procesar
// Las manos y personas externas no provocan
// rechazo automático si no ocultan información.
const documentoProcesable =
  documentoVisible &&
  documentoCompleto &&
  numeroPrincipalCompleto &&
  tipoAdmitido &&
  estadoIA === "APTA";

// 4. Decidir estado
let estado;

if (
  documento.documento_visible === false ||
  documento.documento_completo === false ||
  documento.numero_principal_completo === false ||
  estadoIA === "NO_APTA"
) {
  // Documento ausente, incompleto o con
  // datos esenciales ocultos.
  estado = "NO_APTA";

} else if (
  !tipoAdmitido ||
  documento.numero_principal_completo !== true ||
  !documentoVisible ||
  !documentoCompleto ||
  estadoIA !== "APTA"
) {
  // Información insuficiente o incierta.
  // No se permite continuar automáticamente.
  estado = "REVISION_MANUAL";

} else {
  // Todos los requisitos cumplidos.
  estado = "APTA";
}

const intentos =
  Number(origen.json.intentos ?? 0) + 1;

// 5. Devolver resultado
return [{
  json: {
    ...documento,

    tipo_documento: tipoDocumento,

    estadoOriginalIA: estadoIA,
    estado,

    tipoAdmitido,
    numeroPrincipalCompleto,
    documentoReconocido: tipoAdmitido,
    presentacionCorrecta: documentoProcesable,
    documentoProcesable,

    manoVisible,
    personaVisible,

    errorInterpretacion,

    intentos,
    imagenAnalizada: "intento_1"
  },

  binary: origen.binary
}];

const sharp = require("sharp");

const item = $input.first();

// CONFIGURACIÓN
const TARGET_SIZE = 512;
const BLUR_THRESHOLD = 220;

// Comprobar que llega una imagen
if (!item.binary?.Imagen) {
  throw new Error("Sharp no recibió la imagen aprobada");
}

// Recuperar los bytes de la imagen actual
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  "Imagen"
);

// Obtener dimensiones originales
const metadata = await sharp(buffer).metadata();

// Normalizar a 512x512
const { data, info } = await sharp(buffer)
  .rotate()
  .resize(TARGET_SIZE, TARGET_SIZE, {
    fit: "fill",
    kernel: "cubic"
  })
  .toColourspace("srgb")
  .removeAlpha()
  .raw()
  .toBuffer({ resolveWithObject: true });

// Convertir a escala de grises
const gray = new Float32Array(
  TARGET_SIZE * TARGET_SIZE
);

for (let p = 0; p < gray.length; p++) {
  const i = p * info.channels;

  gray[p] =
    0.299 * data[i] +
    0.587 * data[i + 1] +
    0.114 * data[i + 2];
}

// Calcular varianza del Laplaciano
let sum = 0;
let sumSq = 0;
let n = 0;

for (let y = 1; y < TARGET_SIZE - 1; y++) {
  const row = y * TARGET_SIZE;

  for (let x = 1; x < TARGET_SIZE - 1; x++) {
    const i = row + x;

    const v =
      4 * gray[i] -
      gray[i - 1] -
      gray[i + 1] -
      gray[i - TARGET_SIZE] -
      gray[i + TARGET_SIZE];

    sum += v;
    sumSq += v * v;
    n++;
  }
}

const mean = n ? sum / n : 0;

const variance = n
  ? sumSq / n - mean * mean
  : 0;

// Clasificar nitidez
const borrosa = variance < BLUR_THRESHOLD;

return [{
  json: {
    ...item.json,
    valida: !borrosa,
    estadoNitidez: borrosa ? "BORROSA" : "NITIDA",
    varianza: Number(variance.toFixed(2)),
    umbral: BLUR_THRESHOLD,
    dimensionesOriginales:
      `${metadata.width}x${metadata.height}`,
    dimensionesAnalisis: "512x512",
    motivoNitidez: borrosa
      ? "La imagen no supera el umbral de nitidez."
      : "La imagen supera el umbral de nitidez."
  },
  binary: item.binary
}];

const item = $input.first();

// Utilizar la fotografía que ha pasado Sharp
if (!item.binary?.Imagen) {
  throw new Error(
    "No se recibió la imagen validada"
  );
}

// Mantener los resultados y la imagen correcta
return [{
  json: {
    ...item.json
  },
  binary: item.binary
}];

const contenido = $input.first().json.content;

// Recuperar los resultados de Sharp.
const nitidez = $("03 - Ejecución validate1").first().json;

let datosExtraidos = null;
let errorExtraccion = null;

try {
  if (typeof contenido !== "string" || !contenido.trim()) {
    throw new Error("La IA no devolvió texto");
  }

  const limpio = contenido
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  datosExtraidos = JSON.parse(limpio);

  if (
    !datosExtraidos ||
    typeof datosExtraidos !== "object" ||
    Array.isArray(datosExtraidos)
  ) {
    throw new Error("La respuesta no es un objeto JSON");
  }

  // Comprobar que es una respuesta de extracción.
  const clavesPrincipales = [
    "tipo_documento",
    "numero_documento",
    "nombre",
    "apellidos"
  ];

  if (!clavesPrincipales.some(
    campo => Object.prototype.hasOwnProperty.call(
      datosExtraidos,
      campo
    )
  )) {
    throw new Error("La respuesta no tiene el esquema esperado");
  }

  // NUEVO: identificador personal independiente.
  // Si la IA no lo ha extraído, utilizamos null.
  const identificadorPersonal =
    datosExtraidos.identificador_personal;

  datosExtraidos.identificador_personal =
    typeof identificadorPersonal === "string" &&
    identificadorPersonal.trim()
      ? identificadorPersonal.trim()
      : null;

  // Normalizar campos adicionales sin inventar datos.
  for (const campo of [
    "numero_documento",
    "numero_soporte"
  ]) {
    if (
      typeof datosExtraidos[campo] !== "string" ||
      !datosExtraidos[campo].trim()
    ) {
      datosExtraidos[campo] = null;
    }
  }

} catch (error) {
  errorExtraccion = error.message;
  datosExtraidos = null;
}

// Determinar estado de la extracción.
let estadoFinal;

if (nitidez.valida !== true) {
  estadoFinal = "REVISIÓN MANUAL";

} else if (errorExtraccion) {
  estadoFinal = "ERROR DE EXTRACCIÓN";

} else {
  estadoFinal = "EXTRACCIÓN FINALIZADA";
}

// Conservar información para los siguientes nodos.
return [{
  json: {
    ...nitidez,
    datosExtraidos,
    errorExtraccion,
    estadoFinal,
    verificacionPendiente: true
  }
}];

const item = $input.first();
const datos = item.json.datosExtraidos;

// 1. Comprobar los datos extraídos
if (
  !datos ||
  typeof datos !== "object" ||
  Array.isArray(datos)
) {
  return [{
    json: {
      ...item.json,
      registroNoSQL: null,
      jsonParaMostrar: "Extracción no disponible",
      estadoFinal: "REVISIÓN MANUAL",
      verificacionPendiente: true
    }
  }];
}

// 2. Obtener textos sin inventar valores
const texto = (campo) => {
  const valor = datos[campo];

  return typeof valor === "string" && valor.trim()
    ? valor.trim()
    : null;
};

const tipoDocumento = texto("tipo_documento");

const paisEmisor =
  texto("pais_emisor") ??
  (tipoDocumento === "DNI_NIF" ? "ESP" : null);

// 3. Limpiar identificadores personales
function limpiarIdentificador(valor, pais) {
  if (!valor) return null;

  let limpio = valor.trim();

  // Evitar confundir MRZ con identificadores personales
  if (
    /^P<[A-Z]{3}/i.test(limpio) ||
    (
      limpio.length >= 20 &&
      limpio.includes("<<")
    )
  ) {
    return null;
  }

  if (pais === "CHL") {
    // Quitar etiqueta RUN o RUT
    limpio = limpio.replace(
      /^(?:RUN|RUT)\b[\s:.\-#]*/i,
      ""
    );

  } else if (pais === "BRA") {
    // Quitar etiqueta CPF
    limpio = limpio.replace(
      /^CPF\b[\s:.\-#]*/i,
      ""
    );

  } else if (pais === "PRT") {
    // Quitar etiqueta NIF
    limpio = limpio.replace(
      /^NIF\b[\s:.\-#]*/i,
      ""
    );
  }

  return limpio.trim() || null;
}

// 4. Normalizar nacionalidades conocidas
function normalizarNacionalidad(valor, pais) {
  if (!valor) return null;

  const normalizado = valor
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toUpperCase();

  if (
    pais === "CHL" &&
    ["CHILENA", "CHILENO", "CHL"].includes(normalizado)
  ) {
    return "CHL";
  }

  return valor;
}

// 5. Recuperar campos dudosos
const camposDudosos = Array.isArray(datos.campos_dudosos)
  ? datos.campos_dudosos.filter(
      campo =>
        typeof campo === "string" &&
        campo.trim() &&
        campo !== "fecha_caducidad"
    )
  : [];

// 6. Comprobar formato de fechas
const fecha = (campo, comprobar = true) => {
  const valor = texto(campo);

  if (!valor) return null;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) {
    if (comprobar) camposDudosos.push(campo);
    return null;
  }

  const objetoFecha = new Date(
    valor + "T00:00:00Z"
  );

  if (
    Number.isNaN(objetoFecha.getTime()) ||
    objetoFecha.toISOString().slice(0, 10) !== valor
  ) {
    if (comprobar) camposDudosos.push(campo);
    return null;
  }

  return valor;
};

// 7. Identificadores independientes
const numeroDocumento = texto("numero_documento");

const identificadorPersonal = limpiarIdentificador(
  texto("identificador_personal"),
  paisEmisor
);

const numeroSoporte = texto("numero_soporte");

// 8. NUEVO: recuperar la lectura MRZ especializada
let mrzLinea1 = null;
let mrzLinea2 = null;
let origenMRZ = null;

// Solo los pasaportes utilizan la rama especializada
if (tipoDocumento === "PASAPORTE") {

  try {
    const resultadoMRZ = $(
      "MRZ - Comprobar lectura"
    ).first().json;

    // Recuperar exactamente lo leído por Qwen
    mrzLinea1 =
      typeof resultadoMRZ.mrz_linea_1 === "string" &&
      resultadoMRZ.mrz_linea_1.trim()
        ? resultadoMRZ.mrz_linea_1.trim()
        : null;

    mrzLinea2 =
      typeof resultadoMRZ.mrz_linea_2 === "string" &&
      resultadoMRZ.mrz_linea_2.trim()
        ? resultadoMRZ.mrz_linea_2.trim()
        : null;

    origenMRZ = "LECTURA_ESPECIALIZADA";

  } catch (error) {

    // Si la rama MRZ no se ha ejecutado,
    // no inventamos ni reutilizamos líneas.
    mrzLinea1 = null;
    mrzLinea2 = null;

    origenMRZ = "NO_DISPONIBLE";
  }
}

// IMPORTANTE:
// No completamos líneas de menos de 44 caracteres.
// No sustituimos símbolos.
// No corregimos automáticamente letras ni números.
//
// El nodo Validar datos extraidos comprobará
// posteriormente la estructura y dígitos MRZ.

// 9. Construir registro NoSQL
const registroNoSQL = {
  version_esquema: 1,

  documento: {
    tipo_documento: tipoDocumento,
    pais_emisor: paisEmisor,

    numero_documento: numeroDocumento,
    identificador_personal: identificadorPersonal,
    numero_soporte: numeroSoporte,

    nombre: texto("nombre"),
    apellidos: texto("apellidos"),

    fecha_nacimiento: fecha(
      "fecha_nacimiento",
      true
    ),

    // Caducidad informativa.
    // No se rechaza por estar caducado.
    fecha_caducidad: fecha(
      "fecha_caducidad",
      false
    ),

    nacionalidad: normalizarNacionalidad(
      texto("nacionalidad"),
      paisEmisor
    ),

    // MRZ obtenida mediante la rama especializada
    mrz_linea_1: mrzLinea1,
    mrz_linea_2: mrzLinea2
  },

  evaluacion: {
    estado_nitidez: item.json.estadoNitidez ?? null,
    varianza: item.json.varianza ?? null,
    umbral: item.json.umbral ?? null,
    intento: item.json.intentos ?? null,

    campos_dudosos: [...new Set(camposDudosos)],

    origen_mrz: origenMRZ,

    verificado: false
  },

  metadatos: {
    fecha_procesamiento: new Date().toISOString(),
    origen: "n8n_local"
  }
};

// 10. Devolver resultado
return [{
  json: {
    ...item.json,

    registroNoSQL,

    jsonParaMostrar: JSON.stringify(
      registroNoSQL,
      null,
      2
    )
  }
}];

const item = $input.first();
const registro = item.json.registroNoSQL;

const documento = registro?.documento ?? {};

// 1. Comprobar campos obligatorios
const camposObligatorios = [
  "numero_documento",
  "nombre",
  "apellidos"
];

const camposFaltantes = camposObligatorios.filter(
  campo =>
    typeof documento[campo] !== "string" ||
    !documento[campo].trim()
);

// 2. Campos dudosos
const camposDudosos = Array.isArray(
  registro?.evaluacion?.campos_dudosos
)
  ? registro.evaluacion.campos_dudosos
  : [];

// 3. Recoger resultados del nodo de validación
const validacionDatos = item.json.validacionDatos;

const erroresValidacion = Array.isArray(
  validacionDatos?.errores
)
  ? validacionDatos.errores
  : ["No se ha ejecutado la validación de datos"];

// 4. Normalizar categorías documentales
function normalizarTipo(tipo) {
  if (typeof tipo !== "string" || !tipo.trim()) {
    return null;
  }

  const valor = tipo
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toUpperCase()
    .replace(/[\s-]+/g, "_");

  const tiposDesconocidos = [
    "OTRO",
    "INDETERMINADO",
    "DESCONOCIDO",
    "NO_DOCUMENTO"
  ];

  if (tiposDesconocidos.includes(valor)) {
    return null;
  }

  // Pasaportes internacionales
  if (
    valor.includes("PASAPORTE") ||
    valor.includes("PASSPORT")
  ) {
    return "PASAPORTE";
  }

  // DNI español
  if (valor === "DNI_NIF") {
    return "DNI_NIF";
  }

  // Documentación española de extranjeros
  if ([
    "NIE",
    "TIE",
    "TIE_NIE",
    "CERTIFICADO_NIE",
    "DOCUMENTO_NIF"
  ].includes(valor)) {
    return "TIE_NIE";
  }

  // Identificaciones nacionales internacionales
  if ([
    "ID_NACIONAL",
    "ID_LATAM",
    "NATIONAL_ID",
    "NATIONAL_ID_CARD",
    "CARTAO_CIDADAO",
    "CARTAO_DE_CIDADAO",
    "PERSONALAUSWEIS",
    "CEDULA_IDENTIDAD",
    "CEDULA_DE_IDENTIDAD",
    "CARTE_IDENTITE",
    "CARTA_IDENTITA"
  ].includes(valor)) {
    return "ID_NACIONAL";
  }

  // Mantener denominaciones específicas desconocidas
  return valor;
}

// 5. Comparar clasificación y extracción
const tipoInicial =
  item.json.tipo_documento ?? null;

const tipoExtraido =
  documento.tipo_documento ?? null;

const tipoInicialNormalizado =
  normalizarTipo(tipoInicial);

const tipoExtraidoNormalizado =
  normalizarTipo(tipoExtraido);

const tipoSinDeterminar =
  !tipoInicialNormalizado ||
  !tipoExtraidoNormalizado;

const tipoInconsistente =
  !tipoSinDeterminar &&
  tipoInicialNormalizado !== tipoExtraidoNormalizado;

// 6. Decisión final del proceso
let estadoProceso;

if (item.json.valida !== true) {
  estadoProceso = "IMAGEN_BORROSA";

} else if (!registro || item.json.errorExtraccion) {
  estadoProceso = "ERROR_EXTRACCION";

} else if (
  camposFaltantes.length > 0 ||
  erroresValidacion.length > 0
) {
  // Faltan datos o no superan las validaciones
  estadoProceso = "EXTRACCION_INCOMPLETA";

} else if (
  camposDudosos.length > 0 ||
  tipoInconsistente ||
  tipoSinDeterminar
) {
  estadoProceso = "REVISION_MANUAL";

} else {
  estadoProceso = "PENDIENTE_VERIFICACION";
}

// 7. Devolver resultado
return [{
  json: {
    ...item.json,

    estadoProceso,

    camposFaltantes,
    camposDudosos,
    erroresValidacion,

    tipoInicialNormalizado,
    tipoExtraidoNormalizado,
    tipoInconsistente,
    tipoSinDeterminar,

    verificado: false,
    permitirGuardadoDefinitivo: false
  }
}];

const item = $input.first();
const binary = item.binary ?? {};
const imagen = binary.imagen ?? binary.Imagen;
if (!imagen) {
  return [{json: {apiError: 'FALTA_IMAGEN', mensaje: 'Envía una imagen usando el campo imagen.'}}];
}
return [{json: {...item.json, intentos: 0, apiError: null}, binary: {Imagen: imagen}}];

const v = $input.first().json;

// 1. Estado del procesamiento
const estado = v.estadoProceso ?? "REVISION_MANUAL";

// Solo consideramos superados los controles automáticos
// cuando llegamos a PENDIENTE_VERIFICACION.
const controlesSuperados =
  estado === "PENDIENTE_VERIFICACION";

// 2. Recuperar errores de validación
const erroresValidacion = Array.isArray(v.erroresValidacion)
  ? v.erroresValidacion
  : Array.isArray(v.validacionDatos?.errores)
    ? v.validacionDatos.errores
    : [];

const camposFaltantes = Array.isArray(v.camposFaltantes)
  ? v.camposFaltantes
  : [];

const camposDudosos = Array.isArray(v.camposDudosos)
  ? v.camposDudosos
  : [];

const tipoInconsistente =
  v.tipoInconsistente === true;

// 3. Preparar motivo para el usuario
let motivo = v.motivo ?? null;

if (estado === "IMAGEN_BORROSA") {
  motivo =
    "La imagen no supera el control de nitidez. " +
    "Sube otra fotografía más enfocada.";

} else if (estado === "EXTRACCION_INCOMPLETA") {

  const errorNumero = erroresValidacion.some(
    error => /n[uú]mero|formato/i.test(String(error))
  );

  if (errorNumero || camposFaltantes.includes("numero_documento")) {
    motivo =
      "No se ha podido comprobar correctamente el número " +
      "del documento. Sube otra fotografía donde aparezca " +
      "completo, visible y legible.";
  } else {
    motivo =
      "No se han podido obtener todos los datos obligatorios. " +
      "Sube otra fotografía con la información completa y legible.";
  }

} else if (estado === "REVISION_MANUAL") {
  motivo =
    "No se ha podido confirmar con suficiente seguridad " +
    "la información del documento. Sube otra fotografía " +
    "con todos los datos visibles.";

} else if (estado === "ERROR_EXTRACCION") {
  motivo =
    "Se ha producido un error al analizar el documento. " +
    "Intenta subir la imagen nuevamente.";

} else if (estado === "NO_APTA") {
  motivo =
    "La imagen no cumple los requisitos de identificación. " +
    "Sube otra fotografía sin datos ocultos ni recortes.";

} else if (!controlesSuperados) {
  motivo =
    "No se ha podido completar la validación. " +
    "Sube otra fotografía del documento.";
}

// 4. Conservar información de nitidez
const nitidez = {
  estado: v.estadoNitidez ?? null,
  varianza: v.varianza ?? null,
  umbral: v.umbral ?? null,
  dimensionesOriginales: v.dimensionesOriginales ?? null
};

// 5. Construir respuesta final
return [{
  json: {
    ok: controlesSuperados,

    estado,

    tipo_documento:
      v.tipo_documento ?? null,

    motivo,

    nitidez,

    // No devolver información personal parcial
    // cuando la imagen no supera los controles.
    datos_extraidos: controlesSuperados
      ? (v.datosExtraidos ?? null)
      : null,

    campos_faltantes: camposFaltantes,
    campos_dudosos: camposDudosos,

    tipo_inconsistente: tipoInconsistente,

    errores_validacion: erroresValidacion,

    validacion_formato:
      v.validacionDatos?.formatoNumero ?? "NO_COMPROBADO",

    regla_aplicada:
      v.validacionDatos?.reglaAplicada ?? null,

    solicitar_nueva_imagen: !controlesSuperados,

    registroNoSQL: controlesSuperados
      ? (v.registroNoSQL ?? null)
      : null,

    verificacion_pendiente: controlesSuperados,

    permitir_guardado_definitivo: false
  }
}];

const item = $input.first();
const registro = item.json.registroNoSQL;
const documento = registro?.documento ?? {};

const errores = [];
const advertencias = [];

const pais = String(
  documento.pais_emisor ?? ""
).trim().toUpperCase();

const tipo = String(
  documento.tipo_documento ?? ""
).trim().toUpperCase();

const subtipo = String(
  documento.subtipo_documento ??
  item.json.subtipo_documento ??
  ""
).trim().toUpperCase();

const numero = String(
  documento.numero_documento ?? ""
).trim();

const numeroLimpio = numero
  .toUpperCase()
  .replace(/[\s.\-/]/g, "");

// 1. Campos obligatorios
for (const campo of [
  "numero_documento",
  "nombre",
  "apellidos"
]) {
  const valor = documento[campo];

  if (
    typeof valor !== "string" ||
    !valor.trim()
  ) {
    errores.push(
      `Campo obligatorio ausente: ${campo}`
    );
  }
}

// 2. Caracteres ilegibles
if (/[*#?■●]/u.test(numero)) {
  errores.push(
    "El número contiene caracteres ilegibles"
  );
}

// 3. DNI español
function validarDNI(valor) {
  if (!/^\d{8}[A-Z]$/.test(valor)) {
    return false;
  }

  const letras = "TRWAGMYFPDXBNJZSQVHLCKE";
  const n = Number(valor.slice(0, 8));

  return valor[8] === letras[n % 23];
}

// 4. Cartão de Cidadão portugués
function validarFormatoCC(valor) {
  return /^\d{9}[A-Z0-9]{2}\d$/.test(valor);
}

// 5. CPF brasileño (solo estructura)
function validarFormatoCPF(valor) {
  return /^\d{11}$/.test(valor);
}

// 6. NUEVO: calcular dígito de control MRZ
function calcularDigitoMRZ(cadena) {
  const pesos = [7, 3, 1];
  let suma = 0;

  for (let i = 0; i < cadena.length; i++) {
    const caracter = cadena[i];
    let valor;

    if (caracter === "<") {
      valor = 0;
    } else if (/^[0-9]$/.test(caracter)) {
      valor = Number(caracter);
    } else if (/^[A-Z]$/.test(caracter)) {
      valor = caracter.charCodeAt(0) - 55;
    } else {
      return null;
    }

    suma += valor * pesos[i % 3];
  }

  return String(suma % 10);
}

// 7. NUEVO: validar pasaportes TD3
function validarMRZTD3(linea1, linea2) {
  const erroresMRZ = [];

  if (!linea1 || !linea2) {
    erroresMRZ.push(
      "MRZ incompleta: falta una o ambas líneas"
    );

    return {
      valida: false,
      estado: "FORMATO_INCORRECTO",
      errores: erroresMRZ
    };
  }

  // No completar automáticamente caracteres.
  const l1 = linea1.trim().toUpperCase();
  const l2 = linea2.trim().toUpperCase();

  if (l1.length !== 44 || l2.length !== 44) {
    erroresMRZ.push(
      "MRZ incompleta: cada línea debe tener 44 caracteres"
    );
  }

  if (
    !/^[A-Z0-9<]+$/.test(l1) ||
    !/^[A-Z0-9<]+$/.test(l2)
  ) {
    erroresMRZ.push(
      "MRZ contiene caracteres no permitidos"
    );
  }

  if (erroresMRZ.length > 0) {
    return {
      valida: false,
      estado: "FORMATO_INCORRECTO",
      errores: erroresMRZ
    };
  }

  if (!/^P[A-Z<]/.test(l1)) {
    erroresMRZ.push(
      "MRZ: código de documento TD3 incorrecto"
    );
  }

  if (!/^[A-Z<]{3}$/.test(l1.slice(2, 5))) {
    erroresMRZ.push(
      "MRZ: código de país emisor incorrecto"
    );
  }

  if (!/^[MF<]$/.test(l2[20])) {
    erroresMRZ.push(
      "MRZ: indicador de sexo incorrecto"
    );
  }

  // Número de pasaporte: posiciones 1-9,
  // dígito de control en posición 10.
  const numeroMRZ = l2.slice(0, 9);
  const controlNumero = l2[9];

  if (
    calcularDigitoMRZ(numeroMRZ) !== controlNumero
  ) {
    erroresMRZ.push(
      "MRZ: dígito de control del número incorrecto"
    );
  }

  // Nacimiento: posiciones 14-19,
  // control en posición 20.
  const nacimientoMRZ = l2.slice(13, 19);

  if (
    calcularDigitoMRZ(nacimientoMRZ) !== l2[19]
  ) {
    erroresMRZ.push(
      "MRZ: dígito de control del nacimiento incorrecto"
    );
  }

  // Caducidad: posiciones 22-27,
  // control en posición 28.
  //
  // Solo comprobamos integridad de lectura.
  // NO comprobamos si está caducado.
  const caducidadMRZ = l2.slice(21, 27);

  if (
    calcularDigitoMRZ(caducidadMRZ) !== l2[27]
  ) {
    erroresMRZ.push(
      "MRZ: dígito de control de fecha incorrecto"
    );
  }

  // Datos opcionales: posiciones 29-42,
  // control en posición 43.
  const opcionalesMRZ = l2.slice(28, 42);
  const controlOpcionales = l2[42];

  const opcionalesVacios = /^<+$/.test(
    opcionalesMRZ
  );

  // Cuando todo el campo es relleno,
  // el dígito puede ser 0 o <.
  const opcionalesValidos = opcionalesVacios
    ? ["0", "<"].includes(controlOpcionales)
    : calcularDigitoMRZ(opcionalesMRZ) ===
      controlOpcionales;

  if (!opcionalesValidos) {
    erroresMRZ.push(
      "MRZ: control de datos opcionales incorrecto"
    );
  }

  // Control global: posiciones
  // 1-10 + 14-20 + 22-43.
  const datosGlobales =
    l2.slice(0, 10) +
    l2.slice(13, 20) +
    l2.slice(21, 43);

  if (
    calcularDigitoMRZ(datosGlobales) !== l2[43]
  ) {
    erroresMRZ.push(
      "MRZ: dígito de control global incorrecto"
    );
  }

  return {
    valida: erroresMRZ.length === 0,
    estado: erroresMRZ.length === 0
      ? "FORMATO_CORRECTO"
      : "FORMATO_INCORRECTO",
    errores: erroresMRZ
  };
}

// 8. Seleccionar el validador
let formatoNumero = "NO_COMPROBADO";
let reglaAplicada = null;
let formatoCorrecto = null;
let validacionMRZ = null;

if (tipo === "PASAPORTE") {

  // Una única regla internacional para TD3.
  reglaAplicada = "ICAO_TD3_MRZ";

  validacionMRZ = validarMRZTD3(
    documento.mrz_linea_1,
    documento.mrz_linea_2
  );

  formatoNumero = validacionMRZ.estado;

  errores.push(...validacionMRZ.errores);

} else if (numeroLimpio) {

  if (pais === "ESP" && tipo === "DNI_NIF") {
    reglaAplicada = "ESP_DNI";
    formatoCorrecto = validarDNI(numeroLimpio);

  } else if (
    pais === "PRT" &&
    (
      subtipo.includes("CIDADAO") ||
      subtipo.includes("CIDADÃO") ||
      subtipo === "CC" ||
      (
        tipo === "ID_NACIONAL" &&
        validarFormatoCC(numeroLimpio)
      )
    )
  ) {
    reglaAplicada = "PRT_CARTAO_CIDADAO";
    formatoCorrecto =
      validarFormatoCC(numeroLimpio);

  } else if (
    pais === "BRA" &&
    ["CPF", "CIN"].includes(subtipo)
  ) {
    reglaAplicada = "BRA_CPF";
    formatoCorrecto =
      validarFormatoCPF(numeroLimpio);
  }

  if (reglaAplicada !== null) {
    formatoNumero = formatoCorrecto
      ? "FORMATO_CORRECTO"
      : "FORMATO_INCORRECTO";

    if (!formatoCorrecto) {
      errores.push(
        "El número no cumple el formato esperado"
      );
    }

  } else {
    advertencias.push(
      "Formato documental sin regla específica"
    );
  }
}

// 9. Construir resultado
const validacionDatos = {
  pais,
  tipo,
  subtipo: subtipo || null,

  numeroPresente: numeroLimpio.length > 0,
  formatoNumero,
  reglaAplicada,

  validacionMRZ,

  errores,
  advertencias,

  comprobacionesGeneralesSuperadas:
    errores.length === 0
};

// 10. Devolver sin alterar otros campos
return [{
  json: {
    ...item.json,
    validacionDatos
  },
  binary: item.binary
}];

const sharp = require("sharp");

const item = $input.first();

// Obtener el tipo documental
const tipoDocumento = String(
  item.json.tipo_documento ?? ""
).trim().toUpperCase();

// Conservar la imagen original
if (!item.binary?.Imagen) {
  throw new Error("No se recibió la imagen original");
}

// No recortar DNI, cédulas ni otros documentos
if (tipoDocumento !== "PASAPORTE") {
  return [{
    json: {
      ...item.json,
      mrzRecorteGenerado: false
    },
    binary: item.binary
  }];
}

// Recuperar la imagen original
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  "Imagen"
);

// Corregir orientación EXIF
const imagenOrientada = await sharp(buffer)
  .rotate()
  .toBuffer();

const metadata = await sharp(imagenOrientada)
  .metadata();

const ancho = metadata.width;
const alto = metadata.height;

// Recortar el 30% inferior de la fotografía.
// Aproximación inicial para pasaportes TD3.
const inicioY = Math.floor(alto * 0.70);
const altoRecorte = alto - inicioY;

// Ampliar la zona para facilitar su lectura
const anchoDestino = Math.min(
  2400,
  Math.max(1600, ancho)
);

const recorte = await sharp(imagenOrientada)
  .extract({
    left: 0,
    top: inicioY,
    width: ancho,
    height: altoRecorte
  })
  .resize({
    width: anchoDestino,
    kernel: "lanczos3"
  })
  .png()
  .toBuffer();

// Crear un nuevo binario de n8n
const imagenMRZ = await this.helpers.prepareBinaryData(
  recorte,
  "mrz-recorte.png",
  "image/png"
);

// Mantener la imagen original y añadir el recorte
return [{
  json: {
    ...item.json,
    mrzRecorteGenerado: true,
    mrzRecorteOrigen: `${ancho}x${alto}`
  },
  binary: {
    ...item.binary,
    ImagenMRZ: imagenMRZ
  }
}];

const item = $input.first();

const tipo = String(
  item.json.tipo_documento ?? ""
).trim().toUpperCase();

// Los documentos que no sean pasaportes
// continúan sin procesamiento MRZ.
if (tipo !== "PASAPORTE") {
  return [{
    json: {
      ...item.json,
      mrzBase64: null
    },
    binary: item.binary
  }];
}

// Comprobar que existe el recorte
if (!item.binary?.ImagenMRZ) {
  throw new Error(
    "No se encontró el recorte MRZ del pasaporte"
  );
}

// Recuperar los bytes
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  "ImagenMRZ"
);

// Convertir a Base64
const mrzBase64 = buffer.toString("base64");

// Conservar la imagen original
return [{
  json: {
    ...item.json,
    mrzBase64
  },
  binary: item.binary
}];

