parameters.jsCode:
const respuesta = $input.first().json.message?.content;

let mrz = {};

try {
  mrz = JSON.parse(respuesta);
} catch {
  mrz = {};
}

const ajustes = [];

// Normalizar sin inventar caracteres
function normalizarLinea(valor, nombreCampo) {
  if (typeof valor !== "string" || !valor.trim()) {
    return null;
  }

  let linea = valor.trim();

  // La MRZ utiliza letras mayúsculas
  if (linea !== linea.toUpperCase()) {
    linea = linea.toUpperCase();
    ajustes.push(`${nombreCampo}: mayúsculas`);
  }

  // En la primera línea TD3, los símbolos
  // < del final son caracteres de relleno.
  // Quitar solo el exceso final comprobable.
  if (
    nombreCampo === "mrz_linea_1" &&
    linea.length > 44 &&
    /^<+$/.test(linea.slice(44)) &&
    /<{4,}$/.test(linea.slice(0, 44))
  ) {
    ajustes.push(
      `${nombreCampo}: eliminado relleno sobrante`
    );

    linea = linea.slice(0, 44);
  }

  return linea;
}

const linea1 = normalizarLinea(
  mrz.mrz_linea_1,
  "mrz_linea_1"
);

const linea2 = normalizarLinea(
  mrz.mrz_linea_2,
  "mrz_linea_2"
);

function comprobar(linea) {
  return (
    typeof linea === "string" &&
    linea.length === 44 &&
    /^[A-Z0-9<]{44}$/.test(linea)
  );
}

return [{
  json: {
    mrz_linea_1: linea1,
    mrz_linea_2: linea2,

    longitud_linea_1: linea1?.length ?? 0,
    longitud_linea_2: linea2?.length ?? 0,

    estructura_correcta:
      comprobar(linea1) && comprobar(linea2),

    ajustes_mrz: ajustes
  }
}];

const original = $("MRZ - Preparar Base64").first();
const resultadoMRZ = $input.first().json;

return [{
  json: {
    ...original.json,
    mrzEspecializada: {
      mrz_linea_1: resultadoMRZ.mrz_linea_1 ?? null,
      mrz_linea_2: resultadoMRZ.mrz_linea_2 ?? null,
      estructura_correcta:
        resultadoMRZ.estructura_correcta === true
    }
  },
  binary: original.binary
}];
